test('shows each drug line total as unit price times quantity', () => {
  expect(
    buildAppointmentDrugViews(
      [
        {productId: 'olmetec', quantity: 2, price: 556.4, name: 'Olmetec'},
        {productId: 'xarelto', quantity: 1, price: 1664, name: 'Xarelto'},
        {productId: 'plain', price: 100, name: 'Plain'},
      ],
      {
        olmetec: {drugName: 'Olmetec', subTitle: '20mg'},
        xarelto: {drugName: 'Xarelto', subTitle: '20mg'},
      },
      false,
    ).map((drug) => ({detail: drug.detail, priceLabel: drug.priceLabel})),
  ).toEqual([
    {detail: '20mg, ×2', priceLabel: 'HK$ 1,112.80'},
    {detail: '20mg, ×1', priceLabel: 'HK$ 1,664'},
    {detail: '×', priceLabel: 'HK$ 100'},
  ]);
});
